-- Doova database setup: every migration in order. Generated by supabase/bundle.sh; do not edit by hand.
-- Paste into Supabase → SQL Editor → New query, then Run. Run it once, on an empty project.

-- ===== 20261104000001_extensions_and_types.sql =====
-- 001_extensions_and_types.sql
-- Extensions, enum types and platform settings.
-- All money is stored as integer kobo (₦1 = 100 kobo). Never use floats for money.

create extension if not exists pgcrypto;   -- gen_random_uuid(), digest()
create extension if not exists citext;     -- case-insensitive email

-- ---------------------------------------------------------------------------
-- Enum types
-- ---------------------------------------------------------------------------
create type owner_kind          as enum ('user', 'org');
create type user_status         as enum ('active', 'suspended', 'deleted');
create type org_role            as enum ('owner', 'poster', 'reviewer', 'viewer');   -- 3 Nov: only owners move money
create type payment_provider    as enum ('paystack', 'monnify');                    -- 3 Nov: Titan-Paystack primary, Monnify backup
create type payment_channel     as enum ('bank_transfer', 'card');
create type payment_status      as enum ('pending', 'succeeded', 'failed');
create type payout_status       as enum ('pending', 'processing', 'succeeded', 'failed');
create type task_category       as enum ('native', 'proof_based', 'skill_gated', 'field');
create type task_kind           as enum ('survey', 'review', 'labelling', 'app_test', 'other');
create type staff_role          as enum ('owner', 'moderator', 'finance', 'support');
create type review_mode         as enum ('auto', 'manual');
create type proof_type          as enum ('form', 'file', 'link', 'text', 'screenshot', 'mixed');
create type task_status         as enum (
  'draft', 'pending_funding', 'under_moderation', 'live',
  'paused', 'filled', 'closed', 'settled', 'rejected_by_moderation'
);
create type submission_status   as enum (
  'reserved', 'expired', 'submitted', 'revision_requested',
  'approved', 'rejected', 'appealed', 'rejected_final', 'withdrawn'
);
create type appeal_status       as enum ('open', 'upheld_for_doer', 'upheld_for_creator');
create type ledger_account_type as enum (
  'bank_custody',        -- asset: real money at Paystack (Titan) or Monnify
  'user_wallet',         -- liability: money owed to a user or org
  'task_escrow',         -- liability: money locked for one task's rewards
  'payouts_in_flight',   -- liability: withdrawals sent, not yet confirmed
  'platform_revenue',    -- income: platform fees
  'processor_fees'       -- expense: fees paid to Paystack / Monnify
);
create type data_request_type   as enum ('export', 'delete', 'correct');
create type data_request_status as enum ('received', 'in_progress', 'completed', 'rejected');

-- ---------------------------------------------------------------------------
-- Platform settings (one row per key). Values the business may tune later.
-- Hard business rules that must never be bypassed are ALSO enforced as
-- CHECK constraints on the tables (minimum reward, maximum auto-approve).
-- ---------------------------------------------------------------------------
create table platform_settings (
  key         text primary key,
  value       jsonb not null,
  description text not null,
  updated_at  timestamptz not null default now()
);

insert into platform_settings (key, value, description) values
  ('platform_fee_bps',              '1500',     'Platform fee in basis points (1500 = 15%). Copied onto each task when funded.'),
  ('min_reward_kobo',               '50000',    'Minimum reward per completion: ₦500 (also a CHECK on tasks).'),
  ('max_reward_kobo',               '50000000', 'Maximum reward per completion: ₦500,000 (also a CHECK on tasks).'),
  ('pilot_all_tasks_need_approval', 'true',     'Pilot (4 Nov): every task waits for admin approval.'),
  ('doer_cash_bonuses_enabled',     'false',    'Level, streak and invite cash bonuses: designed, paused until investment (4 Nov).'),
  ('max_auto_approve_hours',        '72',       'Maximum auto-approve window a creator may choose (also a CHECK on tasks).'),
  ('default_auto_approve_hours',    '72',       'Default auto-approve window when the creator does not choose.'),
  ('default_attempt_minutes',       '30',       'Default time a doer holds a reserved slot.'),
  ('appeal_window_hours',           '48',       'How long a doer has to appeal a rejection.'),
  ('min_withdrawal_kobo',           '150000',   'Minimum withdrawal: ₦1,500. Waived when someone closes their account.'),
  ('withdrawal_fee_kobo',           '10000',    'Flat Doova fee per withdrawal: ₦100, deducted from the amount. Platform revenue. Waived on account closure.'),
  ('stamp_duty_threshold_kobo',     '1000000',  'Payouts of ₦10,000 or more attract stamp duty.'),
  ('stamp_duty_kobo',               '5000',     'Stamp duty per qualifying payout: ₦50, passed on to the person withdrawing.'),
  ('chargeback_fee_kobo',           '250000',   'Processor chargeback fee: ₦2,500, debited from the creator wallet.'),
  ('response_retention_days',       '365',      'Survey answers are purged this many days after the task closes unless exported.'),
  ('withdrawals_paused',            'false',    'Set true automatically when daily reconciliation finds a gap.');

create or replace function setting_int(p_key text) returns bigint
language sql stable as $$
  select (value #>> '{}')::bigint from platform_settings where key = p_key
$$;

create or replace function setting_bool(p_key text) returns boolean
language sql stable as $$
  select (value #>> '{}')::boolean from platform_settings where key = p_key
$$;

-- ===== 20261104000002_identity.sql =====
-- 002_identity.sql
-- People, organisations, devices, bank accounts and data-protection requests.

create table users (
  id               uuid primary key default gen_random_uuid(),
  phone            text unique not null,
  email            citext unique,
  full_name        text,
  -- Verification: 0 = phone checked, 1 = NIN checked (3 Nov: NIN only, no selfie, no BVN; done at first withdrawal)
  kyc_tier         smallint not null default 0 check (kyc_tier between 0 and 1),
  -- NIN is stored only as a salted hash after verification (NDPA: minimise). One NIN per account.
  nin_hash         text unique,
  kyc_verified_at  timestamptz,
  tin              text,                         -- optional tax ID
  doer_score       numeric(5,2) not null default 0,
  creator_score    numeric(5,2) not null default 0,
  status           user_status not null default 'active',
  is_flagged       boolean not null default false,
  privacy_consent_at   timestamptz,             -- active tick-box consent at sign-up
  privacy_policy_version text,
  deleted_at       timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

create table organizations (
  id               uuid primary key default gen_random_uuid(),
  name             text not null,
  cac_number       text unique,                  -- RC or BN number, checked with CAC
  kyc_tier         smallint not null default 0 check (kyc_tier between 0 and 1),   -- 1 = CAC checked
  owner_user_id    uuid not null references users(id),
  created_at       timestamptz not null default now()
);

create table org_members (
  org_id     uuid not null references organizations(id) on delete cascade,
  user_id    uuid not null references users(id),
  role       org_role not null,
  added_at   timestamptz not null default now(),
  primary key (org_id, user_id)
);

-- Fraud signal: many accounts on one device.
create table devices (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references users(id),
  fingerprint  text not null,
  first_seen   timestamptz not null default now(),
  last_seen    timestamptz not null default now(),
  unique (user_id, fingerprint)
);
create index devices_fingerprint_idx on devices (fingerprint);

-- Withdrawal destinations. Name must match the verified name before use.
create table bank_accounts (
  id              uuid primary key default gen_random_uuid(),
  owner_type      owner_kind not null,
  owner_id        uuid not null,
  bank_code       text not null,
  account_number  text not null check (account_number ~ '^[0-9]{10}$'),
  account_name    text not null,
  name_matched    boolean not null default false,
  verified_at     timestamptz,
  is_default      boolean not null default false,
  created_at      timestamptz not null default now(),
  unique (owner_type, owner_id, bank_code, account_number)
);
-- Fraud signal: many owners withdrawing to the same bank account.
create index bank_accounts_number_idx on bank_accounts (bank_code, account_number);

-- NDPA: users can request export, correction or deletion of their data.
create table data_requests (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references users(id),
  request_type  data_request_type not null,
  status        data_request_status not null default 'received',
  details       text,
  received_at   timestamptz not null default now(),
  completed_at  timestamptz
);

-- Kyc tier of a wallet owner (user or org).
create or replace function owner_kyc_tier(p_type owner_kind, p_id uuid) returns smallint
language sql stable as $$
  select case p_type
           when 'user' then (select kyc_tier from users where id = p_id)
           when 'org'  then (select kyc_tier from organizations where id = p_id)
         end
$$;

-- Is this user the creator, or a member of the creating organisation? (blocks self-dealing)
create or replace function is_creator_side(p_creator_type owner_kind, p_creator_id uuid, p_user uuid)
returns boolean language sql stable as $$
  select case p_creator_type
           when 'user' then p_creator_id = p_user
           when 'org'  then exists (select 1 from org_members where org_id = p_creator_id and user_id = p_user)
         end
$$;

-- ===== 20261104000003_tasks.sql =====
-- 003_tasks.sql
-- Templates, NDAs, tasks, submissions, proof files and appeals.

create table task_templates (
  id                      uuid primary key default gen_random_uuid(),
  name                    text not null unique,
  category                task_category not null,
  description             text not null,
  form_schema             jsonb not null,          -- questions / fields the doer fills in
  default_proof_type      proof_type not null,
  default_review_mode     review_mode not null,
  suggested_reward_kobo   bigint not null check (suggested_reward_kobo >= 50000),
  is_active               boolean not null default true
);

-- NDA texts. Creators may use the platform standard NDA or upload their own.
create table nda_documents (
  id            uuid primary key default gen_random_uuid(),
  owner_type    owner_kind,                 -- null = platform standard NDA
  owner_id      uuid,
  title         text not null,
  body          text not null,
  version_hash  text not null generated always as (encode(digest(body, 'sha256'), 'hex')) stored,
  created_at    timestamptz not null default now()
);

create table tasks (
  id                      uuid primary key default gen_random_uuid(),
  creator_type            owner_kind not null,
  creator_id              uuid not null,
  created_by_user_id      uuid not null references users(id),
  template_id             uuid references task_templates(id),
  title                   text not null,
  category                task_category not null,
  kind                    task_kind not null default 'survey',
  instructions            text not null,
  form_schema             jsonb,
  proof_type              proof_type not null,
  review_mode             review_mode not null,

  -- Money (kobo)
  reward_kobo             bigint not null check (reward_kobo between 50000 and 50000000), -- 3 Nov: ₦500 to ₦500,000
  slots                   integer not null check (slots between 5 and 5000),             -- 3 Nov: 5 to 5,000 slots
  fee_bps                 integer check (fee_bps between 0 and 10000),    -- copied at funding: 1500 = 15%
  fee_kobo                bigint check (fee_kobo >= 0),                   -- non-refundable
  escrow_kobo             bigint generated always as (reward_kobo * slots) stored,

  -- Timing
  starts_at               timestamptz,
  ends_at                 timestamptz not null,
  estimated_minutes       integer not null default 10 check (estimated_minutes between 1 and 180),  -- 3 Nov
  attempt_minutes         integer not null default 30 check (attempt_minutes between 15 and 1440),  -- slot held this long
  needs_laptop            boolean not null default false,
  auto_approve_hours      integer not null default 72
                            check (auto_approve_hours between 1 and 72),  -- decided: creator picks, max 72h

  -- Eligibility and confidentiality
  eligibility             jsonb not null default '{}',   -- {"states":[..],"min_age":18,"min_doer_score":60,...}
  screening_quiz          jsonb,
  requires_nda            boolean not null default false,
  nda_document_id         uuid references nda_documents(id),
  data_collected_notice   text,                           -- NDPA: what personal data this task collects and why

  status                  task_status not null default 'draft',
  funded_at               timestamptz,
  closed_at               timestamptz,
  settled_at              timestamptz,
  responses_purge_after   timestamptz,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),

  check (not requires_nda or nda_document_id is not null),
  check (attempt_minutes >= 2 * estimated_minutes),       -- 3 Nov: at least twice the estimate
  check (starts_at is null or starts_at < ends_at)
);
create index tasks_feed_idx on tasks (status, ends_at) where status = 'live';
create index tasks_creator_idx on tasks (creator_type, creator_id);

create table nda_signatures (
  id               uuid primary key default gen_random_uuid(),
  task_id          uuid not null references tasks(id),
  user_id          uuid not null references users(id),
  nda_document_id  uuid not null references nda_documents(id),
  version_hash     text not null,          -- exact text signed
  signed_name      text not null,
  signed_at        timestamptz not null default now(),
  ip_address       inet,
  device_id        uuid references devices(id),
  unique (task_id, user_id)
);

create table submissions (
  id                   uuid primary key default gen_random_uuid(),
  task_id              uuid not null references tasks(id),
  doer_id              uuid not null references users(id),
  status               submission_status not null default 'reserved',
  reserved_at          timestamptz not null default now(),
  reserved_until       timestamptz not null,
  submitted_at         timestamptz,
  answers              jsonb,
  score                numeric(6,2),
  reviewed_by_user_id  uuid references users(id),
  reviewed_at          timestamptz,
  reject_reason        text,
  appeal_deadline      timestamptz,
  auto_approved        boolean not null default false,
  answers_purged_at    timestamptz,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  unique (task_id, doer_id)                 -- one attempt per person
);
create index submissions_task_status_idx on submissions (task_id, status);
create index submissions_review_due_idx on submissions (submitted_at) where status = 'submitted';

create table submission_files (
  id             uuid primary key default gen_random_uuid(),
  submission_id  uuid not null references submissions(id) on delete cascade,
  storage_key    text not null,
  mime_type      text not null,
  size_bytes     bigint not null check (size_bytes > 0),
  uploaded_at    timestamptz not null default now()
);

create table appeals (
  id                uuid primary key default gen_random_uuid(),
  submission_id     uuid not null unique references submissions(id),   -- one appeal per submission
  reason            text not null,
  status            appeal_status not null default 'open',
  decided_by_user_id uuid references users(id),
  decided_at        timestamptz,
  decision_note     text,
  created_at        timestamptz not null default now()
);

-- Statuses that hold a slot (count against task.slots).
-- A rejected submission keeps its slot until the appeal window closes, so an appeal
-- won by the doer can always be paid from escrow. After that the slot is freed.
create or replace function submission_holds_slot(s submission_status, reserved_until timestamptz, appeal_deadline timestamptz)
returns boolean language sql stable as $$
  select case
           when s = 'reserved' then reserved_until > now()
           when s in ('submitted', 'revision_requested', 'approved', 'appealed') then true
           when s = 'rejected' then coalesce(appeal_deadline > now(), false)
           else false
         end
$$;

-- Statuses whose reward is still owed or may yet be owed (must stay in escrow at close).
create or replace function submission_reward_pending(s submission_status, reserved_until timestamptz, appeal_deadline timestamptz)
returns boolean language sql stable as $$
  select case
           when s = 'reserved' then reserved_until > now()
           when s in ('submitted', 'revision_requested', 'appealed') then true
           when s = 'rejected' then coalesce(appeal_deadline > now(), false)
           else false
         end
$$;

-- ===== 20261104000004_ledger.sql =====
-- 004_ledger.sql
-- Double-entry ledger. Every money movement is one transaction whose debits equal
-- its credits. Entries are insert-only: mistakes are fixed with reversing
-- transactions, never edits or deletes.

create table ledger_accounts (
  id             uuid primary key default gen_random_uuid(),
  -- Stable lookup code, e.g. 'platform:bank_custody:paystack', 'user:<uuid>:wallet', 'task:<uuid>:escrow'
  code           text not null unique,
  type           ledger_account_type not null,
  owner_type     text,                -- 'platform' | 'user' | 'org' | 'task'
  owner_id       uuid,
  provider       payment_provider,    -- for bank_custody accounts
  currency       char(3) not null default 'NGN',
  -- Debit-normal: assets and expenses. Credit-normal: liabilities and income.
  normal_side    text not null check (normal_side in ('debit', 'credit')),
  -- Cached balance in the account's normal direction (kept by trigger, verifiable from entries).
  balance_kobo   bigint not null default 0,
  created_at     timestamptz not null default now()
);

create table ledger_transactions (
  id               uuid primary key default gen_random_uuid(),
  kind             text not null check (kind in (
                     'deposit', 'fund_task', 'release_reward', 'refund_escrow',
                     'withdrawal_request', 'payout_confirmed', 'payout_reversed',
                     'payout_fee', 'chargeback', 'adjustment')),
  -- Every caller passes a key; replaying the same webhook / approval is ignored, not paid twice.
  idempotency_key  text not null unique,
  reference_type   text,
  reference_id     uuid,
  memo             text,
  created_at       timestamptz not null default now()
);

create table ledger_entries (
  id              bigserial primary key,
  transaction_id  uuid not null references ledger_transactions(id),
  account_id      uuid not null references ledger_accounts(id),
  direction       text not null check (direction in ('debit', 'credit')),
  amount_kobo     bigint not null check (amount_kobo > 0),
  created_at      timestamptz not null default now()
);
create index ledger_entries_account_idx on ledger_entries (account_id, created_at);
create index ledger_entries_txn_idx on ledger_entries (transaction_id);

-- ---------------------------------------------------------------------------
-- Rule: insert-only
-- ---------------------------------------------------------------------------
create or replace function ledger_forbid_change() returns trigger
language plpgsql as $$
begin
  raise exception 'ledger rows are insert-only; post a reversing transaction instead';
end $$;

create trigger ledger_entries_no_update  before update or delete on ledger_entries
  for each row execute function ledger_forbid_change();
create trigger ledger_txn_no_update      before update or delete on ledger_transactions
  for each row execute function ledger_forbid_change();
create trigger ledger_entries_no_truncate before truncate on ledger_entries
  for each statement execute function ledger_forbid_change();

-- ---------------------------------------------------------------------------
-- Rule: cached balance follows every entry
-- ---------------------------------------------------------------------------
create or replace function ledger_apply_entry() returns trigger
language plpgsql as $$
begin
  update ledger_accounts
     set balance_kobo = balance_kobo +
         case when new.direction = normal_side then new.amount_kobo else -new.amount_kobo end
   where id = new.account_id;
  return new;
end $$;

create trigger ledger_entries_apply after insert on ledger_entries
  for each row execute function ledger_apply_entry();

-- ---------------------------------------------------------------------------
-- Rule: every transaction balances (checked at COMMIT, after all its entries exist)
-- ---------------------------------------------------------------------------
create or replace function ledger_check_balanced() returns trigger
language plpgsql as $$
declare
  v_debits  bigint;
  v_credits bigint;
begin
  select coalesce(sum(amount_kobo) filter (where direction = 'debit'), 0),
         coalesce(sum(amount_kobo) filter (where direction = 'credit'), 0)
    into v_debits, v_credits
    from ledger_entries where transaction_id = new.transaction_id;
  if v_debits <> v_credits then
    raise exception 'unbalanced ledger transaction %: debits % <> credits %',
      new.transaction_id, v_debits, v_credits;
  end if;
  return null;
end $$;

create constraint trigger ledger_entries_balanced
  after insert on ledger_entries
  deferrable initially deferred
  for each row execute function ledger_check_balanced();

-- ---------------------------------------------------------------------------
-- Account helpers
-- ---------------------------------------------------------------------------
create or replace function ledger_normal_side(t ledger_account_type) returns text
language sql immutable as $$
  select case when t in ('bank_custody', 'processor_fees') then 'debit' else 'credit' end
$$;

-- Get or create an account by code.
create or replace function ledger_account(
  p_code text, p_type ledger_account_type,
  p_owner_type text default null, p_owner_id uuid default null,
  p_provider payment_provider default null
) returns uuid
language plpgsql as $$
declare v_id uuid;
begin
  select id into v_id from ledger_accounts where code = p_code;
  if v_id is null then
    insert into ledger_accounts (code, type, owner_type, owner_id, provider, normal_side)
    values (p_code, p_type, p_owner_type, p_owner_id, p_provider, ledger_normal_side(p_type))
    on conflict (code) do nothing
    returning id into v_id;
    if v_id is null then
      select id into v_id from ledger_accounts where code = p_code;
    end if;
  end if;
  return v_id;
end $$;

create or replace function wallet_account(p_owner_type owner_kind, p_owner_id uuid) returns uuid
language sql as $$
  select ledger_account(p_owner_type::text || ':' || p_owner_id || ':wallet', 'user_wallet',
                        p_owner_type::text, p_owner_id)
$$;

create or replace function escrow_account(p_task uuid) returns uuid
language sql as $$
  select ledger_account('task:' || p_task || ':escrow', 'task_escrow', 'task', p_task)
$$;

create or replace function custody_account(p_provider payment_provider) returns uuid
language sql as $$
  select ledger_account('platform:bank_custody:' || p_provider, 'bank_custody',
                        'platform', null, p_provider)
$$;

create or replace function platform_account(p_type ledger_account_type) returns uuid
language sql as $$
  select ledger_account('platform:' || p_type, p_type, 'platform', null)
$$;

create or replace function account_balance(p_account uuid) returns bigint
language sql stable as $$
  select balance_kobo from ledger_accounts where id = p_account
$$;

-- ---------------------------------------------------------------------------
-- post_transaction: the ONLY way money moves.
--   p_entries: [{"account": uuid, "direction": "debit"|"credit", "amount": kobo}, ...]
-- Returns the transaction id, or the existing id if the idempotency key was seen before.
-- Balances that must never go negative are checked after posting; a chargeback is
-- the one movement allowed to push a wallet below zero (the creator then owes it).
-- ---------------------------------------------------------------------------
create or replace function post_transaction(
  p_kind text, p_idempotency_key text, p_entries jsonb,
  p_reference_type text default null, p_reference_id uuid default null,
  p_memo text default null
) returns uuid
language plpgsql as $$
declare
  v_txn      uuid;
  v_entry    jsonb;
  v_debits   bigint := 0;
  v_credits  bigint := 0;
  v_bad      record;
begin
  select id into v_txn from ledger_transactions where idempotency_key = p_idempotency_key;
  if v_txn is not null then
    return v_txn;                         -- already posted: do nothing
  end if;

  for v_entry in select * from jsonb_array_elements(p_entries) loop
    if (v_entry->>'direction') = 'debit' then
      v_debits := v_debits + (v_entry->>'amount')::bigint;
    else
      v_credits := v_credits + (v_entry->>'amount')::bigint;
    end if;
  end loop;
  if v_debits <> v_credits or v_debits = 0 then
    raise exception 'post_transaction %: debits % must equal credits % and be > 0',
      p_kind, v_debits, v_credits;
  end if;

  -- Lock the touched accounts in a fixed order to avoid deadlocks.
  perform 1 from ledger_accounts
   where id in (select (e->>'account')::uuid from jsonb_array_elements(p_entries) e)
   order by id for update;

  insert into ledger_transactions (kind, idempotency_key, reference_type, reference_id, memo)
  values (p_kind, p_idempotency_key, p_reference_type, p_reference_id, p_memo)
  returning id into v_txn;

  insert into ledger_entries (transaction_id, account_id, direction, amount_kobo)
  select v_txn, (e->>'account')::uuid, e->>'direction', (e->>'amount')::bigint
    from jsonb_array_elements(p_entries) e;

  for v_bad in
    select a.code, a.type, a.balance_kobo from ledger_accounts a
     where a.id in (select (e->>'account')::uuid from jsonb_array_elements(p_entries) e)
       and a.balance_kobo < 0
       and a.type in ('user_wallet', 'task_escrow', 'payouts_in_flight', 'bank_custody')
  loop
    -- A chargeback is forced on us by the card network: the provider takes the money
    -- even if that drives its balance (and the creator's wallet) below zero.
    if not (p_kind = 'chargeback' and v_bad.type in ('user_wallet', 'bank_custody')) then
      raise exception 'insufficient balance in % (would be % kobo)', v_bad.code, v_bad.balance_kobo
        using errcode = 'P0001';
    end if;
  end loop;

  return v_txn;
end $$;

-- ---------------------------------------------------------------------------
-- Verification views
-- ---------------------------------------------------------------------------
-- Cached balance vs recomputed from entries; any row here is a bug.
create view v_ledger_balance_drift as
select a.code, a.balance_kobo as cached_kobo,
       coalesce(sum(case when e.direction = a.normal_side then e.amount_kobo else -e.amount_kobo end), 0) as computed_kobo
  from ledger_accounts a left join ledger_entries e on e.account_id = a.id
 group by a.id
having a.balance_kobo <> coalesce(sum(case when e.direction = a.normal_side then e.amount_kobo else -e.amount_kobo end), 0);

-- Whole-ledger check: assets + expenses must equal liabilities + income.
create view v_ledger_trial_balance as
select
  sum(balance_kobo) filter (where normal_side = 'debit')  as debit_side_kobo,
  sum(balance_kobo) filter (where normal_side = 'credit') as credit_side_kobo
from ledger_accounts;

-- ===== 20261104000005_payments.sql =====
-- 005_payments.sql
-- External money: virtual accounts, incoming payments, payouts, chargebacks,
-- webhook log and daily reconciliation.
-- Primary provider: Paystack (Titan-Paystack dedicated accounts). Backup: Monnify (Moniepoint).
-- Each creator gets a dedicated account number; doers get none (3 Nov).

create table virtual_accounts (
  id               uuid primary key default gen_random_uuid(),
  owner_type       owner_kind not null,
  owner_id         uuid not null,
  provider         payment_provider not null,
  issuing_bank     text not null,          -- 'Titan-Paystack' | 'Moniepoint'
  account_number   text not null check (account_number ~ '^[0-9]{10}$'),
  account_name     text not null,
  provider_ref     text,
  is_active        boolean not null default true,
  created_at       timestamptz not null default now(),
  unique (provider, account_number),
  unique (owner_type, owner_id, provider)
);

-- Raw webhooks, stored before processing. (provider, event_id) makes replays harmless.
create table webhook_events (
  id            bigserial primary key,
  provider      payment_provider not null,
  event_id      text not null,
  event_type    text not null,
  payload       jsonb not null,
  received_at   timestamptz not null default now(),
  processed_at  timestamptz,
  error         text,
  unique (provider, event_id)
);

-- Money in: bank transfer to a virtual account, or card checkout.
create table payments (
  id                     uuid primary key default gen_random_uuid(),
  owner_type             owner_kind not null,
  owner_id               uuid not null,
  provider               payment_provider not null,
  channel                payment_channel not null,
  provider_ref           text not null,
  virtual_account_id     uuid references virtual_accounts(id),
  amount_kobo            bigint not null check (amount_kobo > 0),   -- gross amount paid
  fee_kobo               bigint not null default 0 check (fee_kobo >= 0),  -- processor collection fee
  net_kobo               bigint generated always as (amount_kobo - fee_kobo) stored,
  status                 payment_status not null default 'pending',
  card_3ds_verified      boolean,                                    -- required for card payments
  ledger_transaction_id  uuid references ledger_transactions(id),
  received_at            timestamptz not null default now(),
  unique (provider, provider_ref),
  check (fee_kobo < amount_kobo)
);

-- Money out: withdrawal to a name-matched bank account.
create table payouts (
  id                       uuid primary key default gen_random_uuid(),
  owner_type               owner_kind not null,
  owner_id                 uuid not null,
  bank_account_id          uuid not null references bank_accounts(id),
  provider                 payment_provider not null,
  amount_kobo              bigint not null check (amount_kobo > 0),   -- debited from wallet
  withdrawal_fee_kobo      bigint not null default 0 check (withdrawal_fee_kobo >= 0),  -- Doova's flat fee (revenue)
  stamp_duty_kobo          bigint not null default 0,                 -- passed on to the person withdrawing
  transfer_kobo            bigint generated always as (amount_kobo - withdrawal_fee_kobo - stamp_duty_kobo) stored,  -- reaches their bank
  is_account_closure       boolean not null default false,            -- minimum and fee waived
  processor_fee_kobo       bigint,                                     -- absorbed by the platform
  status                   payout_status not null default 'pending',
  provider_ref             text,
  failure_reason           text,
  requested_at             timestamptz not null default now(),
  completed_at             timestamptz,
  request_txn_id           uuid references ledger_transactions(id),
  settle_txn_id            uuid references ledger_transactions(id),
  unique (provider, provider_ref),
  check (amount_kobo - withdrawal_fee_kobo - stamp_duty_kobo > 0)
);
create index payouts_owner_day_idx on payouts (owner_type, owner_id, requested_at);

-- Card disputes. The amount plus the processor's fee is debited from the creator's wallet.
create table chargebacks (
  id                     uuid primary key default gen_random_uuid(),
  payment_id             uuid not null unique references payments(id),
  amount_kobo            bigint not null check (amount_kobo > 0),
  fee_kobo               bigint not null default 0,
  provider_ref           text,
  reason                 text,
  ledger_transaction_id  uuid references ledger_transactions(id),
  received_at            timestamptz not null default now()
);

-- Daily: ledger custody balance vs the bank/provider statement.
create table reconciliations (
  id                   bigserial primary key,
  provider             payment_provider not null,
  statement_date       date not null,
  statement_kobo       bigint not null,
  ledger_kobo          bigint not null,
  difference_kobo      bigint generated always as (statement_kobo - ledger_kobo) stored,
  withdrawals_paused   boolean not null,
  created_at           timestamptz not null default now(),
  unique (provider, statement_date)
);

-- ===== 20261104000006_workflows.sql =====
-- 006_workflows.sql
-- Business operations as database functions. The app calls these instead of
-- writing money or status columns directly, so every rule lives in one place.
--
-- Money in        record_deposit
-- Tasks           fund_task, close_task, refund_task_escrow
-- Doing tasks     sign_nda, reserve_slot, submit_submission
-- Reviewing       approve_submission, reject_submission, request_revision
-- Appeals         open_appeal, decide_appeal
-- Money out       request_withdrawal, confirm_payout, fail_payout
-- Risk            record_chargeback, reconcile_custody
-- Housekeeping    run_scheduled_jobs, purge_expired_responses

-- ===========================================================================
-- Money in
-- ===========================================================================
-- Called from the Paystack / Monnify webhook handler once the provider confirms money arrived.
-- The creator bears the collection fee: the wallet is credited with the net amount.
create or replace function record_deposit(
  p_provider payment_provider, p_provider_ref text,
  p_owner_type owner_kind, p_owner_id uuid,
  p_channel payment_channel, p_amount_kobo bigint, p_fee_kobo bigint default 0,
  p_virtual_account_id uuid default null, p_card_3ds_verified boolean default null
) returns uuid
language plpgsql as $$
declare
  v_payment uuid;
  v_txn     uuid;
begin
  select id into v_payment from payments where provider = p_provider and provider_ref = p_provider_ref;
  if v_payment is not null then
    return v_payment;                                     -- webhook replay
  end if;

  if p_channel = 'card' then
    if coalesce(p_card_3ds_verified, false) is false then
      raise exception 'card payments must pass 3-D Secure';
    end if;
    if owner_kyc_tier(p_owner_type, p_owner_id) < 1 then
      raise exception 'card funding requires tier 1 verification';
    end if;
  end if;

  insert into payments (owner_type, owner_id, provider, channel, provider_ref, virtual_account_id,
                        amount_kobo, fee_kobo, status, card_3ds_verified)
  values (p_owner_type, p_owner_id, p_provider, p_channel, p_provider_ref, p_virtual_account_id,
          p_amount_kobo, p_fee_kobo, 'succeeded', p_card_3ds_verified)
  returning id into v_payment;

  v_txn := post_transaction(
    'deposit', 'deposit:' || p_provider || ':' || p_provider_ref,
    jsonb_build_array(
      jsonb_build_object('account', custody_account(p_provider), 'direction', 'debit',  'amount', p_amount_kobo - p_fee_kobo),
      jsonb_build_object('account', wallet_account(p_owner_type, p_owner_id), 'direction', 'credit', 'amount', p_amount_kobo - p_fee_kobo)
    ),
    'payment', v_payment, 'Wallet top-up');

  update payments set ledger_transaction_id = v_txn where id = v_payment;
  return v_payment;
end $$;

-- ===========================================================================
-- Tasks
-- ===========================================================================
-- Locks reward × slots in escrow and takes the 15% fee, all from the creator's wallet.
-- The task goes to moderation (or straight live for trusted creators).
create or replace function fund_task(p_task uuid, p_skip_moderation boolean default false)
returns uuid
language plpgsql as $$
declare
  t        tasks%rowtype;
  v_fee    bigint;
  v_bps    integer := setting_int('platform_fee_bps');
  v_wallet uuid;
  v_txn    uuid;
begin
  select * into t from tasks where id = p_task for update;
  if not found then raise exception 'task % not found', p_task; end if;
  if t.status not in ('draft', 'pending_funding') then
    raise exception 'task % is % and cannot be funded', p_task, t.status;
  end if;
  if t.ends_at <= now() then raise exception 'task end date is in the past'; end if;
  -- 4 Nov creator tiers: slot caps and task types by tier (spending never changes a tier).
  perform check_creator_tier_allows(t);

  v_fee := (t.escrow_kobo * v_bps + 9999) / 10000;        -- round up to the kobo
  v_wallet := wallet_account(t.creator_type, t.creator_id);

  v_txn := post_transaction(
    'fund_task', 'fund:' || p_task,
    jsonb_build_array(
      jsonb_build_object('account', v_wallet, 'direction', 'debit', 'amount', t.escrow_kobo + v_fee),
      jsonb_build_object('account', escrow_account(p_task), 'direction', 'credit', 'amount', t.escrow_kobo),
      jsonb_build_object('account', platform_account('platform_revenue'), 'direction', 'credit', 'amount', v_fee)
    ),
    'task', p_task, 'Escrow + platform fee');

  update tasks
     set fee_bps = v_bps, fee_kobo = v_fee, funded_at = now(), updated_at = now(),
         status = case when p_skip_moderation then 'live'::task_status else 'under_moderation'::task_status end
   where id = p_task;
  return v_txn;
end $$;

-- Moderation decision on a funded task. Approved → live. Rejected → everything
-- (escrow AND fee) goes back to the creator, since the task never ran.
create or replace function moderate_task(p_task uuid, p_approve boolean, p_note text default null)
returns void
language plpgsql as $$
declare t tasks%rowtype;
begin
  select * into t from tasks where id = p_task for update;
  if t.status <> 'under_moderation' then raise exception 'task % is not under moderation', p_task; end if;
  if p_approve then
    update tasks set status = 'live', updated_at = now() where id = p_task;
    return;
  end if;
  perform post_transaction(
    'refund_escrow', 'moderation_refund:' || p_task,
    jsonb_build_array(
      jsonb_build_object('account', escrow_account(p_task), 'direction', 'debit', 'amount', t.escrow_kobo),
      jsonb_build_object('account', platform_account('platform_revenue'), 'direction', 'debit', 'amount', t.fee_kobo),
      jsonb_build_object('account', wallet_account(t.creator_type, t.creator_id), 'direction', 'credit', 'amount', t.escrow_kobo + t.fee_kobo)
    ),
    'task', p_task, coalesce('Rejected by moderation: ' || p_note, 'Rejected by moderation'));
  update tasks set status = 'settled', settled_at = now(), closed_at = now(), updated_at = now()
   where id = p_task;
end $$;

-- Close a task (deadline passed or creator cancels). Open reviews and live
-- reservations finish; unused escrow goes back to the creator. Fee is not refunded.
create or replace function close_task(p_task uuid) returns bigint
language plpgsql as $$
declare t tasks%rowtype;
begin
  select * into t from tasks where id = p_task for update;
  if t.status in ('closed', 'settled') then
    return refund_task_escrow(p_task);
  end if;
  if t.status not in ('live', 'paused', 'filled', 'under_moderation', 'rejected_by_moderation') then
    raise exception 'task % is % and cannot be closed', p_task, t.status;
  end if;
  update tasks
     set status = 'closed', closed_at = now(), updated_at = now(),
         responses_purge_after = now() + make_interval(days => setting_int('response_retention_days')::int)
   where id = p_task;
  return refund_task_escrow(p_task);
end $$;

-- Refund whatever escrow is not needed for rewards that may still be owed.
-- Safe to call repeatedly (scheduled job calls it until the task settles).
create or replace function refund_task_escrow(p_task uuid) returns bigint
language plpgsql as $$
declare
  t          tasks%rowtype;
  v_escrow   uuid := escrow_account(p_task);
  v_balance  bigint;
  v_pending  integer;
  v_refund   bigint;
begin
  select * into t from tasks where id = p_task for update;
  if t.status <> 'closed' then return 0; end if;

  v_balance := account_balance(v_escrow);
  select count(*) into v_pending from submissions
   where task_id = p_task and submission_reward_pending(status, reserved_until, appeal_deadline);
  v_refund := v_balance - t.reward_kobo * v_pending;

  if v_refund > 0 then
    perform post_transaction(
      'refund_escrow', 'refund:' || p_task || ':' || v_balance || ':' || v_pending,
      jsonb_build_array(
        jsonb_build_object('account', v_escrow, 'direction', 'debit', 'amount', v_refund),
        jsonb_build_object('account', wallet_account(t.creator_type, t.creator_id), 'direction', 'credit', 'amount', v_refund)
      ),
      'task', p_task, 'Unused escrow returned to creator');
  else
    v_refund := 0;
  end if;

  if account_balance(v_escrow) = 0 and v_pending = 0 then
    update tasks set status = 'settled', settled_at = now(), updated_at = now() where id = p_task;
  end if;
  return v_refund;
end $$;

-- ===========================================================================
-- Doing tasks
-- ===========================================================================
create or replace function sign_nda(
  p_task uuid, p_user uuid, p_signed_name text,
  p_ip inet default null, p_device uuid default null
) returns uuid
language plpgsql as $$
declare
  t     tasks%rowtype;
  v_id  uuid;
begin
  select * into t from tasks where id = p_task;
  if not t.requires_nda then raise exception 'task % does not require an NDA', p_task; end if;
  insert into nda_signatures (task_id, user_id, nda_document_id, version_hash, signed_name, ip_address, device_id)
  select p_task, p_user, d.id, d.version_hash, p_signed_name, p_ip, p_device
    from nda_documents d where d.id = t.nda_document_id
  on conflict (task_id, user_id) do nothing
  returning id into v_id;
  return coalesce(v_id, (select id from nda_signatures where task_id = p_task and user_id = p_user));
end $$;

-- Hold one slot for the doer. The task row lock makes over-booking impossible.
create or replace function reserve_slot(p_task uuid, p_doer uuid) returns uuid
language plpgsql as $$
declare
  t        tasks%rowtype;
  u        users%rowtype;
  v_held   integer;
  v_sub    submissions%rowtype;
  v_until  timestamptz;
begin
  select * into t from tasks where id = p_task for update;
  if not found then raise exception 'task % not found', p_task; end if;
  if t.status <> 'live' then raise exception 'task is not accepting submissions (%)', t.status; end if;
  if now() >= t.ends_at or (t.starts_at is not null and now() < t.starts_at) then
    raise exception 'task is outside its start and end dates';
  end if;

  select * into u from users where id = p_doer;
  if u.status <> 'active' then raise exception 'account is not active'; end if;
  if is_creator_side(t.creator_type, t.creator_id, p_doer) then
    raise exception 'creators cannot complete their own tasks';
  end if;
  perform check_doer_level_allows(t, u);
  if t.requires_nda and not exists (
       select 1 from nda_signatures s join nda_documents d on d.id = s.nda_document_id
        where s.task_id = p_task and s.user_id = p_doer and s.version_hash = d.version_hash) then
    raise exception 'sign the NDA before starting this task';
  end if;

  select count(*) into v_held from submissions
   where task_id = p_task and submission_holds_slot(status, reserved_until, appeal_deadline);
  if v_held >= t.slots then raise exception 'task is full'; end if;

  v_until := least(now() + make_interval(mins => t.attempt_minutes), t.ends_at);

  select * into v_sub from submissions where task_id = p_task and doer_id = p_doer for update;
  if found then
    if v_sub.status = 'reserved' and v_sub.reserved_until > now() then
      return v_sub.id;                                   -- already holding a slot
    elsif v_sub.status in ('expired', 'withdrawn') then
      update submissions set status = 'reserved', reserved_at = now(), reserved_until = v_until,
                             answers = null, updated_at = now()
       where id = v_sub.id;
      return v_sub.id;
    else
      raise exception 'one attempt per person: you already have a % submission', v_sub.status;
    end if;
  end if;

  insert into submissions (task_id, doer_id, reserved_until)
  values (p_task, p_doer, v_until)
  returning id into v_sub.id;
  return v_sub.id;
end $$;

-- Doer submits. Native (auto-review) tasks are approved instantly when they pass checks.
create or replace function submit_submission(
  p_submission uuid, p_doer uuid, p_answers jsonb,
  p_score numeric default null, p_passed_checks boolean default true
) returns submission_status
language plpgsql as $$
declare
  s  submissions%rowtype;
  t  tasks%rowtype;
begin
  select * into s from submissions where id = p_submission for update;
  if s.doer_id <> p_doer then raise exception 'not your submission'; end if;
  if s.status not in ('reserved', 'revision_requested') then
    raise exception 'submission is % and cannot be submitted', s.status;
  end if;
  if s.status = 'reserved' and s.reserved_until <= now() then
    update submissions set status = 'expired', updated_at = now() where id = p_submission;
    raise exception 'time limit passed; the slot was released';
  end if;

  select * into t from tasks where id = s.task_id;

  update submissions
     set status = 'submitted', submitted_at = now(), answers = p_answers,
         score = p_score, updated_at = now()
   where id = p_submission;

  if t.review_mode = 'auto' then
    if p_passed_checks then
      perform approve_submission(p_submission, null, true);
      return 'approved';
    else
      update submissions set status = 'rejected_final', reject_reason = 'Did not pass automatic checks',
                             reviewed_at = now(), updated_at = now()
       where id = p_submission;
      return 'rejected_final';
    end if;
  end if;
  return 'submitted';
end $$;

-- ===========================================================================
-- Reviewing
-- ===========================================================================
create or replace function can_review(p_task uuid, p_user uuid) returns boolean
language sql stable as $$
  select case t.creator_type
           when 'user' then t.creator_id = p_user
           when 'org'  then exists (select 1 from org_members m
                                     where m.org_id = t.creator_id and m.user_id = p_user
                                       and m.role in ('owner', 'reviewer'))
         end
    from tasks t where t.id = p_task
$$;

-- Moves one reward from task escrow to the doer's wallet: instant, ledger only.
-- p_reviewer null = automatic (auto-review task, auto-approve timer, or appeal decided by staff).
create or replace function approve_submission(p_submission uuid, p_reviewer uuid, p_auto boolean default false)
returns uuid
language plpgsql as $$
declare
  s     submissions%rowtype;
  t     tasks%rowtype;
  v_txn uuid;
begin
  select * into s from submissions where id = p_submission for update;
  select * into t from tasks where id = s.task_id;
  if s.status not in ('submitted', 'appealed') then
    raise exception 'submission is % and cannot be approved', s.status;
  end if;
  if p_reviewer is not null and not can_review(t.id, p_reviewer) then
    raise exception 'user % may not review this task', p_reviewer;
  end if;

  v_txn := post_transaction(
    'release_reward', 'release:' || p_submission,
    jsonb_build_array(
      jsonb_build_object('account', escrow_account(t.id), 'direction', 'debit', 'amount', t.reward_kobo),
      jsonb_build_object('account', wallet_account('user', s.doer_id), 'direction', 'credit', 'amount', t.reward_kobo)
    ),
    'submission', p_submission, 'Reward released');

  update submissions
     set status = 'approved', reviewed_by_user_id = p_reviewer, reviewed_at = now(),
         auto_approved = p_auto, updated_at = now()
   where id = p_submission;
  return v_txn;
end $$;

create or replace function reject_submission(p_submission uuid, p_reviewer uuid, p_reason text)
returns void
language plpgsql as $$
declare s submissions%rowtype;
begin
  select * into s from submissions where id = p_submission for update;
  if s.status <> 'submitted' then raise exception 'submission is % and cannot be rejected', s.status; end if;
  if not can_review(s.task_id, p_reviewer) then raise exception 'user % may not review this task', p_reviewer; end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'a rejection reason is required'; end if;
  update submissions
     set status = 'rejected', reject_reason = p_reason, reviewed_by_user_id = p_reviewer,
         reviewed_at = now(), updated_at = now(),
         appeal_deadline = now() + make_interval(hours => setting_int('appeal_window_hours')::int)
   where id = p_submission;
end $$;

-- One revision request per submission; the doer gets a fresh attempt window.
create or replace function request_revision(p_submission uuid, p_reviewer uuid, p_note text)
returns void
language plpgsql as $$
declare
  s submissions%rowtype;
  t tasks%rowtype;
begin
  select * into s from submissions where id = p_submission for update;
  select * into t from tasks where id = s.task_id;
  if s.status <> 'submitted' then raise exception 'submission is % and cannot be revised', s.status; end if;
  if not can_review(s.task_id, p_reviewer) then raise exception 'user % may not review this task', p_reviewer; end if;
  if s.reject_reason like 'REVISION:%' then raise exception 'only one revision request is allowed'; end if;
  update submissions
     set status = 'revision_requested', reject_reason = 'REVISION: ' || p_note,
         reserved_until = now() + make_interval(mins => t.attempt_minutes), updated_at = now()
   where id = p_submission;
end $$;

-- ===========================================================================
-- Appeals (decided by platform staff)
-- ===========================================================================
create or replace function open_appeal(p_submission uuid, p_doer uuid, p_reason text) returns uuid
language plpgsql as $$
declare
  s    submissions%rowtype;
  v_id uuid;
begin
  select * into s from submissions where id = p_submission for update;
  if s.doer_id <> p_doer then raise exception 'not your submission'; end if;
  if s.status <> 'rejected' or s.appeal_deadline <= now() then
    raise exception 'this rejection can no longer be appealed';
  end if;
  insert into appeals (submission_id, reason) values (p_submission, p_reason) returning id into v_id;
  update submissions set status = 'appealed', updated_at = now() where id = p_submission;
  return v_id;
end $$;

create or replace function decide_appeal(p_appeal uuid, p_staff uuid, p_for_doer boolean, p_note text)
returns void
language plpgsql as $$
declare a appeals%rowtype;
begin
  select * into a from appeals where id = p_appeal for update;
  if a.status <> 'open' then raise exception 'appeal already decided'; end if;
  update appeals
     set status = case when p_for_doer then 'upheld_for_doer'::appeal_status else 'upheld_for_creator'::appeal_status end,
         decided_by_user_id = p_staff, decided_at = now(), decision_note = p_note
   where id = p_appeal;
  if p_for_doer then
    perform approve_submission(a.submission_id, null, false);
    update submissions set reviewed_by_user_id = p_staff where id = a.submission_id;
  else
    update submissions set status = 'rejected_final', updated_at = now() where id = a.submission_id;
  end if;
end $$;

-- ===========================================================================
-- Money out
-- ===========================================================================
-- Moves the amount from the wallet to payouts-in-flight; the app then calls the
-- provider's transfer API and reports back with confirm_payout or fail_payout.
-- No withdrawal hold (decided). Doova's flat ₦100 fee is deducted from the amount and
-- booked as revenue; stamp duty is passed on; the provider's transfer fee is absorbed.
-- Closing an account (p_close_account) withdraws the whole balance with no minimum and no fee.
create or replace function request_withdrawal(
  p_owner_type owner_kind, p_owner_id uuid, p_requested_by uuid,
  p_bank_account uuid, p_amount_kobo bigint,
  p_provider payment_provider default 'paystack',
  p_close_account boolean default false
) returns uuid
language plpgsql as $$
declare
  b         bank_accounts%rowtype;
  v_tier    smallint := owner_kyc_tier(p_owner_type, p_owner_id);
  v_duty    bigint := 0;
  v_fee     bigint := 0;
  v_payout  uuid;
  v_txn     uuid;
begin
  if setting_bool('withdrawals_paused') then
    raise exception 'withdrawals are paused while the ledger is reconciled';
  end if;
  if v_tier < 1 then raise exception 'withdrawals require a NIN check first'; end if;
  if p_owner_type = 'user' and p_requested_by <> p_owner_id then
    raise exception 'you can only withdraw from your own wallet';
  end if;
  if p_owner_type = 'org' and not exists (
       select 1 from org_members where org_id = p_owner_id and user_id = p_requested_by
          and role = 'owner') then
    raise exception 'only the business owner can withdraw';
  end if;
  if p_close_account then
    if p_amount_kobo <> (select balance_kobo from ledger_accounts where id = wallet_account(p_owner_type, p_owner_id)) then
      raise exception 'closing an account withdraws the whole balance';
    end if;
  else
    if p_amount_kobo < setting_int('min_withdrawal_kobo') then
      raise exception 'minimum withdrawal is % kobo', setting_int('min_withdrawal_kobo');
    end if;
    v_fee := setting_int('withdrawal_fee_kobo');
  end if;

  select * into b from bank_accounts where id = p_bank_account;
  if not found or b.owner_type <> p_owner_type or b.owner_id <> p_owner_id then
    raise exception 'bank account does not belong to this wallet';
  end if;
  if not b.name_matched or b.verified_at is null then
    raise exception 'bank account name must match the verified name';
  end if;

  -- 3 Nov: no maximum and no daily limit; the only limit is the ₦1,500 minimum.

  if p_amount_kobo >= setting_int('stamp_duty_threshold_kobo') then
    v_duty := setting_int('stamp_duty_kobo');
  end if;

  if p_amount_kobo - v_fee - v_duty <= 0 then
    raise exception 'amount is too small to cover the fees';
  end if;

  insert into payouts (owner_type, owner_id, bank_account_id, provider, amount_kobo,
                       withdrawal_fee_kobo, stamp_duty_kobo, is_account_closure)
  values (p_owner_type, p_owner_id, p_bank_account, p_provider, p_amount_kobo,
          v_fee, v_duty, p_close_account)
  returning id into v_payout;

  -- Wallet pays the full amount; the fee is revenue now, the rest is in flight to the bank.
  v_txn := post_transaction(
    'withdrawal_request', 'withdraw:' || v_payout,
    jsonb_build_array(
      jsonb_build_object('account', wallet_account(p_owner_type, p_owner_id), 'direction', 'debit', 'amount', p_amount_kobo),
      jsonb_build_object('account', platform_account('payouts_in_flight'), 'direction', 'credit', 'amount', p_amount_kobo - v_fee)
    ) || case when v_fee > 0 then jsonb_build_array(
      jsonb_build_object('account', platform_account('platform_revenue'), 'direction', 'credit', 'amount', v_fee)
    ) else '[]'::jsonb end,
    'payout', v_payout, 'Withdrawal requested');

  update payouts set request_txn_id = v_txn where id = v_payout;
  return v_payout;
end $$;

-- Provider confirmed the transfer. Money leaves custody: transfer + stamp duty (= amount - fee),
-- plus the provider's transfer fee, which the platform absorbs as an expense.
create or replace function confirm_payout(p_payout uuid, p_provider_ref text, p_processor_fee_kobo bigint)
returns void
language plpgsql as $$
declare
  p     payouts%rowtype;
  v_txn uuid;
begin
  select * into p from payouts where id = p_payout for update;
  if p.status = 'succeeded' then return; end if;              -- webhook replay
  if p.status not in ('pending', 'processing') then
    raise exception 'payout is % and cannot be confirmed', p.status;
  end if;

  v_txn := post_transaction(
    'payout_confirmed', 'payout_ok:' || p_payout,
    jsonb_build_array(
      jsonb_build_object('account', platform_account('payouts_in_flight'), 'direction', 'debit', 'amount', p.amount_kobo - p.withdrawal_fee_kobo),
      jsonb_build_object('account', custody_account(p.provider), 'direction', 'credit', 'amount', p.amount_kobo - p.withdrawal_fee_kobo)
    ),
    'payout', p_payout, 'Payout confirmed by provider');

  if p_processor_fee_kobo > 0 then
    perform post_transaction(
      'payout_fee', 'payout_fee:' || p_payout,
      jsonb_build_array(
        jsonb_build_object('account', platform_account('processor_fees'), 'direction', 'debit', 'amount', p_processor_fee_kobo),
        jsonb_build_object('account', custody_account(p.provider), 'direction', 'credit', 'amount', p_processor_fee_kobo)
      ),
      'payout', p_payout, 'Transfer fee absorbed by platform');
  end if;

  update payouts
     set status = 'succeeded', provider_ref = p_provider_ref, processor_fee_kobo = p_processor_fee_kobo,
         completed_at = now(), settle_txn_id = v_txn
   where id = p_payout;
end $$;

-- Provider rejected the transfer: the money goes back to the wallet in full, fee included.
create or replace function fail_payout(p_payout uuid, p_reason text) returns void
language plpgsql as $$
declare
  p     payouts%rowtype;
  v_txn uuid;
begin
  select * into p from payouts where id = p_payout for update;
  if p.status = 'failed' then return; end if;
  if p.status not in ('pending', 'processing') then
    raise exception 'payout is % and cannot be failed', p.status;
  end if;
  v_txn := post_transaction(
    'payout_reversed', 'payout_fail:' || p_payout,
    jsonb_build_array(
      jsonb_build_object('account', platform_account('payouts_in_flight'), 'direction', 'debit', 'amount', p.amount_kobo - p.withdrawal_fee_kobo),
      jsonb_build_object('account', wallet_account(p.owner_type, p.owner_id), 'direction', 'credit', 'amount', p.amount_kobo)
    ) || case when p.withdrawal_fee_kobo > 0 then jsonb_build_array(
      jsonb_build_object('account', platform_account('platform_revenue'), 'direction', 'debit', 'amount', p.withdrawal_fee_kobo)
    ) else '[]'::jsonb end,
    'payout', p_payout, 'Payout failed, returned to wallet with the fee');
  update payouts set status = 'failed', failure_reason = p_reason, completed_at = now(), settle_txn_id = v_txn
   where id = p_payout;
end $$;

-- ===========================================================================
-- Risk
-- ===========================================================================
-- Card dispute: the provider takes the amount plus its fee from custody; the creator's
-- wallet is debited the same, even if that makes it negative (they then owe the platform,
-- and cannot fund or withdraw until it is repaid). The owner is flagged for review.
create or replace function record_chargeback(
  p_payment uuid, p_amount_kobo bigint, p_provider_ref text, p_reason text
) returns uuid
language plpgsql as $$
declare
  pay    payments%rowtype;
  v_fee  bigint := setting_int('chargeback_fee_kobo');
  v_cb   uuid;
  v_txn  uuid;
begin
  select * into pay from payments where id = p_payment;
  if pay.channel <> 'card' then raise exception 'only card payments can be charged back'; end if;

  insert into chargebacks (payment_id, amount_kobo, fee_kobo, provider_ref, reason)
  values (p_payment, p_amount_kobo, v_fee, p_provider_ref, p_reason)
  on conflict (payment_id) do nothing
  returning id into v_cb;
  if v_cb is null then return (select id from chargebacks where payment_id = p_payment); end if;

  v_txn := post_transaction(
    'chargeback', 'chargeback:' || p_payment,
    jsonb_build_array(
      jsonb_build_object('account', wallet_account(pay.owner_type, pay.owner_id), 'direction', 'debit', 'amount', p_amount_kobo + v_fee),
      jsonb_build_object('account', custody_account(pay.provider), 'direction', 'credit', 'amount', p_amount_kobo + v_fee)
    ),
    'chargeback', v_cb, 'Card chargeback + processor fee');

  update chargebacks set ledger_transaction_id = v_txn where id = v_cb;
  if pay.owner_type = 'user' then
    update users set is_flagged = true, updated_at = now() where id = pay.owner_id;
  end if;
  return v_cb;
end $$;

-- Daily: compare ledger custody with the provider statement. Any gap pauses withdrawals.
create or replace function reconcile_custody(p_provider payment_provider, p_date date, p_statement_kobo bigint)
returns bigint
language plpgsql as $$
declare
  v_ledger bigint := account_balance(custody_account(p_provider));
  v_diff   bigint := p_statement_kobo - v_ledger;
begin
  insert into reconciliations (provider, statement_date, statement_kobo, ledger_kobo, withdrawals_paused)
  values (p_provider, p_date, p_statement_kobo, v_ledger, v_diff <> 0)
  on conflict (provider, statement_date) do update
     set statement_kobo = excluded.statement_kobo, ledger_kobo = excluded.ledger_kobo,
         withdrawals_paused = excluded.withdrawals_paused, created_at = now();
  if v_diff <> 0 then
    update platform_settings set value = 'true', updated_at = now() where key = 'withdrawals_paused';
  end if;
  return v_diff;
end $$;

-- ===========================================================================
-- Housekeeping: run every minute from a scheduler (pg_cron or the app's job runner)
-- ===========================================================================
create or replace function run_scheduled_jobs() returns jsonb
language plpgsql as $$
declare
  v_expired   integer;
  v_auto      integer := 0;
  v_final     integer;
  v_closed    integer := 0;
  v_settled   integer := 0;
  r           record;
begin
  -- 1. Release reservations whose time ran out.
  update submissions set status = 'expired', updated_at = now()
   where status = 'reserved' and reserved_until <= now();
  get diagnostics v_expired = row_count;

  -- 2. Auto-approve submissions the creator did not review in time.
  for r in
    select s.id from submissions s join tasks t on t.id = s.task_id
     where s.status = 'submitted'
       and s.submitted_at + make_interval(hours => t.auto_approve_hours) <= now()
  loop
    perform approve_submission(r.id, null, true);
    v_auto := v_auto + 1;
  end loop;

  -- 3. Rejections whose appeal window passed become final (frees the slot).
  update submissions set status = 'rejected_final', updated_at = now()
   where status = 'rejected' and appeal_deadline <= now();
  get diagnostics v_final = row_count;

  -- 4. Close tasks past their end date.
  for r in select id from tasks where status in ('live', 'paused', 'filled') and ends_at <= now() loop
    perform close_task(r.id);
    v_closed := v_closed + 1;
  end loop;

  -- 5. Refund and settle closed tasks as their last submissions resolve.
  for r in select id from tasks where status = 'closed' loop
    perform refund_task_escrow(r.id);
  end loop;
  select count(*) into v_settled from tasks where status = 'settled' and settled_at >= now() - interval '1 minute';

  return jsonb_build_object('expired', v_expired, 'auto_approved', v_auto, 'rejections_finalised', v_final,
                            'tasks_closed', v_closed, 'tasks_settled_recently', v_settled);
end $$;

-- NDPA retention: clear survey answers after the retention period (run daily).
create or replace function purge_expired_responses() returns integer
language plpgsql as $$
declare v_count integer;
begin
  update submissions s
     set answers = null, answers_purged_at = now(), updated_at = now()
    from tasks t
   where t.id = s.task_id and t.responses_purge_after <= now()
     and s.answers is not null;
  get diagnostics v_count = row_count;
  return v_count;
end $$;

-- ===========================================================================
-- Read views for the app
